/* Constants */
export const STEPS = [{"name":"reading the dump","step":"dump"},{"name":"reading checks","step":"checks"},{"name":"building logic","step":"logic"},{"name":"placing items","step":"placing"},{"name":"writing the mod","step":"writing"},{"name":"writing the spoiler","step":"spoiler"},{"name":"installing","step":"installing"},{"name":"rebuilding the game","step":"rebuilding"}] as const;

export const TRACKER_COLUMNS = 3 as const;

/* Types */
/**  A status change or a log line. */
export type ApEvent = {
	status: ApStatus,
	line: string | null,
};

/**  What the page shows: the status and the log so far. */
export type ApState = {
	status: ApStatus,
	log: string[],
};

export type ApStatus = "offline" | "connecting" | "connected" | "refused";

/**  Each line, to whichever page is listening. */
export type AppLogEvent = Line;

/**  Where the Logs page picks up after a reload. */
export type AppLogState = {
	/**  The newest [`CAP`] lines, oldest first. */
	lines: Line[],
	/**  This run's file. */
	file: string | null,
	/**  Why there's no file. */
	unsaved: string | null,
};

/**  What applying a test setup did. */
export type Applied = {
	done: string[],
	/**  Goals that held before Apply, which prove nothing. */
	held: string[],
};

export type Build = {
	status: BuildStatus,
	/**  What the user is told, when the build isn't current. */
	text: string | null,
	/**  The target has a rebuild command. */
	command: boolean,
};

/**  Whether a game's last build saw the hook patch installed now. */
export type BuildStatus = 
/**  The build has the installed patch, or neither has one. */
{ kind: "current" } | 
/**  The patch changed, came or went since the build. */
{ kind: "stale" } | 
/**  The build refused the patch, saying why. */
{ kind: "refused"; note: string } | 
/**  The build lists no patches, so it may not load them. */
{ kind: "unrecorded" };

/**  One drawn cell. */
export type Cell = {
	section: Section,
	label: string,
	/**  The icon's name: the held tier, else the first. */
	icon: string,
	/**  What draws in its place when the game's art is off. */
	glyph: Glyph,
	/**  0 when missing, else which tier is held, from 1. */
	tier: number,
	/**  0 where a dungeon has no such item, drawn fainter than missing. */
	tiers: number,
	count: number | null,
	/**  Set on a row's first cell, in a section laid out in rows. */
	row: DungeonRow | null,
};

/**  One changed value, to print or to send to the app. */
export type Change = {
	hash: number,
	/**  The name, else `#hash`, with `[i]` for an array element. */
	name: string,
	label: string | null,
	kind: string,
	/**  `a -> b`, or what changed when the values can't be shown. */
	change: string,
};

/**  A spot checked or unchecked in the installed seed. */
export type ChecksEvent = {
	hash: string,
	checked: boolean,
};

export type ChecksState = {
	/**  The installed seed's history entry, if one is installed. */
	id: number | null,
	rows: Row[],
	/**  Its shuffled doors, none with the setting off. */
	doors: DoorRow[],
};

export type Choice = {
	id: string,
	label: string,
	/**
	 *  Toggles this pick turns on, and other choices' picks it makes as
	 *  `id=option`, shown locked.
	 */
	forces: string[],
	/**  Start inventory words this pick gives, shown held. */
	starts: string[],
};

export type Config = {
	/**
	 *  The game dump: a `.nup`, or an extracted romfs folder. The CLI's
	 *  `--game` wins over it.
	 */
	game?: string | null,
	/**  Randomizer setting values by id. Missing ids take their default. */
	settings?: { [key in string]: Value },
	targets?: Target[],
	/**  Name of the target Play opens. */
	picked?: string | null,
	/**  The app's test setup, kept with each seed it builds. */
	test?: TestSetup,
	/**  Test setups kept by name, to switch between. */
	saved_tests?: { [key in string]: TestSetup },
	/**
	 *  The plando draft the next seed gets: chest hash to the item it must
	 *  hold. The hashes are JSON keys, so strings, and reach the UI whole.
	 */
	place?: { [key in string]: string },
	/**  Plandos kept by name, to load into `place`. */
	plandos?: { [key in string]: { [key in string]: string } },
	/**
	 *  The app shows its developer tools: the dev panel, Test setup, and
	 *  the targets' scripted-play fields. Off, a hidden test setup leaves
	 *  seeds alone. Every seed carries the dev panel's hook either way, so
	 *  hiding the tools never changes the hook patch.
	 */
	dev_tools?: boolean,
	/**
	 *  Draw item icons from the game dump. zootr-nx ships none of the
	 *  game's art, so it's off until the person turns it on.
	 */
	game_assets?: boolean,
	/**
	 *  Don't ask GitHub for a newer release. Inverted so the derived
	 *  `Default` leaves checks on.
	 */
	no_update_check?: boolean,
};

/**  One placement the panel's warp lists. */
export type DevActor = {
	actor: string,
	/**  Its instance hash, as text: a u64 doesn't fit a JavaScript number. */
	hash: string,
	/**  Its own `Name`, telling it from the actor's other placements. */
	label: string | null,
};

/**  A live actor a placement made, for the panel's Live actors. */
export type DevNear = {
	/**  The placement's hash, as text: a u64 doesn't fit a JS number. */
	hash: string,
	actor: string,
	/**
	 *  The placement's own `Name`, when the map's files have it: an actor
	 *  a seed adds has none.
	 */
	label: string | null,
	distance: number | null,
	hidden: Hidden,
};

/**
 *  What the game is doing, as far as a teleport cares, and the dev
 *  switches it holds.
 */
export type DevState = {
	map: string,
	child: boolean,
	loading: boolean,
	/**  An event is playing. */
	event: boolean,
	switches: DevSwitches,
};

/**  The dev switches: what the hook keeps at its cap on Link's update. */
export type DevSwitches = {
	health: boolean,
	magic: boolean,
	/**  Every ammo kind and rupees. */
	resources: boolean,
};

/**  A GameData value as the dev panel's Set shows it. */
export type DevValue = {
	info: Info,
	/**  The game is up and its memory could be read. */
	game: boolean,
	/**
	 *  What it holds now, as the Live tab shows it. `None` without the
	 *  game, or for a value it doesn't keep.
	 */
	live: string | null,
	/**
	 *  What a BoolExp works out, as infix: the game keeps no value for it,
	 *  so it's set through the values it reads.
	 */
	expr: string | null,
};

/**  A dungeon door and the dungeon behind it. */
export type Door = {
	/**  The door, by `--door`'s id: the dungeon behind it in vanilla. */
	id: string,
	/**  Where the door stands, by name. */
	area: string,
	/**  The dungeon behind it in vanilla, by name. */
	vanilla: string,
	/**  The dungeon behind it in this seed: its id, then its name. */
	dungeon: string,
	dungeon_name: string,
};

/**  One shuffled door on the Checks tab. */
export type DoorRow = {
	/**
	 *  The door, by `--door`'s id: the dungeon behind it in vanilla. The
	 *  doors' ids are also every dungeon a door can lead to.
	 */
	id: string,
	name: string,
	/**  The dungeon behind it in vanilla, by name, labelling `id`. */
	vanilla: string,
	/**  The dungeon behind it by id, once Link has been through. */
	found: string | null,
	/**  The player's guess, by id, until the door is revealed. */
	pick: string | null,
};

/**  The installed seed's doors, once one is revealed or hidden again. */
export type DoorsEvent = {
	doors: DoorRow[],
};

/**  The dungeon a row of the Dungeons section is for. */
export type DungeonRow = {
	/**  What starts the row, such as "FoT". */
	short: string,
	/**  The full name, such as "Forest Temple". */
	name: string,
};

/**  One element of a save value to set, as text its type takes. */
export type Edit = {
	hash: number,
	/**  The element: 0 for anything that isn't an array. */
	index?: number,
	value: string,
};

/**  How a run ended. */
export type End = { kind: "done" } | { kind: "failed"; error: string } | { kind: "stopped"; took_off: boolean };

export type Event = { type: "Started"; session: Session } | 
/**  A change `at` seconds into the session, from an autosave if `save`. */
{ type: "Row"; at: number; save: boolean; change: Change } | 
/**  A value muted for changing too often, or by hand if `manual`. */
{ type: "Muted"; hash: number; name: string; manual: boolean } | 
/**  A marker `at` seconds into the session, saying what happened. */
{ type: "Marked"; at: number; text: string } | { type: "Unsaved"; reason: string } | { type: "Ended"; reason: string } | { type: "Status"; status: LiveStatus };

/**  One group's header, with its rows when it's open. */
export type FlagGroup = {
	name: string,
	/**  Values that pass the filters. */
	count: number,
	/**  Of those, how many differ from their default. */
	changed: number,
	open: boolean,
	rows: FlagRow[],
};

/**  What the tab asks for. */
export type FlagQuery = {
	/**  Matched against the name, the hash in hex and any label. */
	search: string,
	/**  Only values of these types, every type when empty. */
	kinds: string[],
	/**  Only values that differ from what a new game starts with. */
	changed: boolean,
	/**  Only values the pending edits change. */
	staged: boolean,
	/**
	 *  Each open group, to how many rows it shows. A search opens the
	 *  groups it hits, at a page each.
	 */
	open: { [key in string]: number },
};

/**  One value. */
export type FlagRow = {
	hash: number,
	/**  The name, else `#hash`. */
	name: string,
	label: string | null,
	kind: string,
	/**  The field each element is edited in. */
	input: Input,
	choices: string[],
	/**
	 *  One per element: one for a scalar. Empty when the type can't be
	 *  read, with `size` saying how big it is.
	 */
	values: string[],
	size: number,
	default: string | null,
	changed: boolean,
	staged: boolean,
};

export type FlagsView = {
	groups: FlagGroup[],
	/**  Every type the save holds, for the type filter. */
	kinds: string[],
};

/**  What the dev panel, the test setup and plando pick from. */
export type GameOptions = {
	/**  Every arrival point, `MAP/SPOT`, both ages. */
	places: string[],
	/**  Child `MAP/SPOT`s a new game can start at. */
	spawns: string[],
	/**  Pouch item actors. */
	items: string[],
	/**  GameData names, sorted. */
	names: string[],
	/**  Each quest and its steps, in order. */
	quests: { [key in string]: string[] },
};

/**
 *  What a cell draws when the game's art is off. Tiers share one, as the
 *  swords and the three wallets do.
 */
export type Glyph = "sticks" | "nuts" | "bombs" | "bombchus" | "bow" | "slingshot" | "ocarina" | "hookshot" | "boomerang" | "beans" | "scrub-seeds" | "lens" | "hammer" | "fire-arrow" | "fire-medallion" | "ice-arrow" | "light-arrow" | "light-medallion" | "dins-fire" | "farores-wind" | "nayrus-love" | "bottle" | "egg" | "cucco" | "letter" | "mask" | "truth-mask" | "mushroom" | "saw" | "sword" | "prescription" | "frog" | "eye-drops" | "claim-check" | "shield" | "tunic" | "iron-boots" | "hover-boots" | "gauntlets" | "scale" | "wallet" | "bomb-bag" | "quiver" | "bullet-bag" | "heart-piece" | "heart" | "rupee" | "magic" | "spin" | "defense" | "gerudo-card" | "agony-stone" | "skulltula" | "song" | "stone" | "forest-medallion" | "water-medallion" | "spirit-medallion" | "shadow-medallion" | "small-key" | "boss-key" | "map" | "compass" | "unknown";

/**  One of a test setup's goals, read from the game. */
export type Goal = {
	name: string,
	want: string,
	/**  The value it holds, as the Live tab shows it. */
	now: string | null,
	met: boolean,
	/**  Why it couldn't be read. The other goals still are. */
	error: string | null,
};

/**  An item Link starts with. */
export type Held = {
	item: string,
	name: string,
	count: number,
	/**  The checks, by hash, whose pool slots its copies left. */
	from?: string[],
	/**
	 *  Where the copies no check gave came from (a preset's label, the
	 *  starting inventory), when there are any.
	 */
	via?: string | null,
};

/**  Whether an actor's model is hidden, and by whom. */
export type Hidden = "shown" | 
/**  By [`hide`]. */
"ours" | 
/**  By the game itself (an actor waiting on a scene). */
"game";

export type IconSize = "Small" | "Medium" | "Large";

/**  What GameData says about one value. */
export type Info = {
	/**  The table: `Bool`, `Enum`, `Int`... */
	kind: string,
	input: Input,
	/**
	 *  `true` and `false` for a Bool, an Enum's value names in the
	 *  definition's order, else empty.
	 */
	choices: string[],
	/**  What a new game starts with, for a scalar. */
	default: string | null,
};

/**  The field one element of a value is edited in. */
export type Input = 
/**  One of the value's choices. */
"choice" | "number" | "text" | 
/**  Comma-separated floats: `x,y` or `x,y,z`. */
"vector" | 
/**  Shown, not written: what [`encode`] can't write. */
"read";

/**  What a click on a cell asks for. */
export type Intent = 
/**  The next tier, wrapping to none after the last. */
"up" | 
/**  The tier before, wrapping from none to the last. */
"down" | 
/**  This many of a counted item, kept within its cap. */
{ count: number };

/**  The grid changed, or its options did. */
export type ItemsEvent = ItemsState;

/**  What the Items tab and the pop out draw. */
export type ItemsState = {
	cells: Cell[],
	options: TrackerOptions,
	/**  The icons come from the dump: game assets are on and a dump is set. */
	game_art: boolean,
};

/**
 *  The Items tab: the grid and the Status panel, as the pending edits
 *  leave the save.
 */
export type ItemsView = {
	/**  The tracker's default layout. */
	sections: Placement[],
	cells: Cell[],
	/**  How many each counted cell can hold, in `cells`' order. */
	caps: (number | null)[],
	/**  Whether a pending edit changes each cell. */
	staged: boolean[],
	status: StatusField[],
	/**
	 *  Which of the starting inventory's givers gives each cell, by index,
	 *  in `cells`' order: a setting's item a click leaves alone. Empty on
	 *  the Save page.
	 */
	locked: (number | null)[],
};

export type Kind = { type: "toggle"; default: boolean } | 
/**  One of `options`, saved by id. */
{ type: "choice"; default: string; options: Choice[] } | 
/**
 *  What a new game starts holding, the save editor's grid: a
 *  [`starting::Start`].
 */
{ type: "inventory"; default: StartInventory };

/**  What a seed is for, in the player's words. Both may be blank. */
export type Label = {
	name?: string,
	note?: string,
};

/**  How bad a line is. */
export type Level = "error" | "warn" | "info" | "debug";

/**
 *  One line of the log, numbered so a page that loads mid-run can tell
 *  which lines its snapshot already holds.
 */
export type Line = {
	seq: number,
	/**  The local time, as `HH:MM:SS`. */
	time: string,
	level: Level,
	text: string,
};

/**  Every Live tab event, to whichever page is listening. */
export type LiveEvent = Numbered;

/**  What recording is doing between sessions. */
export type LiveStatus = 
/**
 *  The game isn't running, or can't be read until it starts again, with
 *  the reason.
 */
{ state: "Waiting"; reason: string | null } | 
/**  The game is running but live reads aren't ready yet. */
{ state: "Attaching"; reason: string } | { state: "Recording"; session: Session };

/**  A check the player set aside, or a note on it. */
export type Mark = { kind: "Skipped" } | { kind: "Note"; text: string };

/**
 *  An event and where it falls in the stream, so a page that loads
 *  mid-session can tell which events its snapshot already holds.
 */
export type Numbered = {
	seq: number,
	event: Event,
};

/**
 *  What's waiting to be saved: the presets turned on, then single edits
 *  on top of them.
 */
export type Pending = {
	presets: string[],
	edits: Edit[],
};

/**  Where a section sits in the grid and how wide it draws. */
export type Placement = {
	section: Section,
	/**  1 to `COLUMNS`. */
	column: number,
	/**  Icons per row. */
	width: number,
	shown: boolean,
};

/**  A check a plando can pin an item to, named as a seed's report names it. */
export type PlandoCheck = {
	hash: string,
	area: string,
	/**  Its name (`Spot::name`). */
	place: string,
	/**  What it holds in the vanilla game. */
	vanilla: string,
	/**  The setting that would deal it, when these settings don't. */
	needs: string | null,
};

/**  An item a plando can pin. */
export type PlandoItem = {
	actor: string,
	name: string,
};

/**
 *  What a plando can pick from with these settings, and why the deal
 *  refuses `fixed`, if it does.
 */
export type PlandoOptions = {
	/**
	 *  Each check once, by area then place: the dealt ones, then those one
	 *  more setting would deal.
	 */
	checks: PlandoCheck[],
	/**  The pool's items once each, by name. */
	items: PlandoItem[],
	/**  Why the deal refuses `fixed`, if it does. */
	error: string | null,
};

export type Rebuild = {
	/**  What rebuilds the game, as arguments. `{game}` becomes the game dump. */
	command?: string[],
	/**
	 *  The build's patch list, when it isn't in the game folder that holds
	 *  `mods/<name>`.
	 */
	manifest?: string | null,
};

/**  An item Link gets outside the shuffle, in the round that collects it. */
export type RoundEvent = {
	round: number,
	name: string,
};

/**  One row of the Checks tab. */
export type Row = {
	spot: Spot,
	checked: boolean,
	/**
	 *  The spot's Bool, which the tab can label. A spot ticked by its
	 *  per-placement flag has none.
	 */
	flag: number | null,
	/**  The user's label for the flag, which wins over the spot's names. */
	label: string | null,
	mark: Mark | null,
};

/**  What saving changed. */
export type SaveEdit = {
	/**  Each value as `name: old -> new`. */
	log: string[],
	backup: string,
};

/**  A preset an existing save can take. */
export type SavePreset = {
	name: string,
	label: string,
	what: string,
};

export type Section = "Inventory" | "Trade" | "Masks" | "Equipment" | "Upgrades" | "Quest" | "Songs" | "Stones" | "Medallions" | "Dungeons";

export type Session = {
	source: Source,
	/**  Why live reads aren't used. */
	reason: string | null,
	log: string | null,
	/**  Why the log isn't being written. */
	unsaved: string | null,
	/**  Local time it started, `HH:MM`. */
	started: string,
};

export type SettingDef = {
	id: string,
	group: string,
	label: string,
	description: string,
	kind: Kind,
	/**  When the parent is on, this one is too, whatever its own value. */
	parent: string | null,
	/**
	 *  The toggle that must be on for this one to do anything. While it's
	 *  off, the app greys this one out.
	 */
	requires: string | null,
	/**  The section of its panel it sits in. */
	section: string,
	/**  The line under that section's title: see [`Place::about`]. */
	section_about: string,
	/**  Its section is a checklist: see [`Place::list`]. */
	list: boolean,
	/**
	 *  Start inventory words a value gives outside the start inventory, as
	 *  `(value, words)`: a toggle's `on`, else an option's id. The grid
	 *  shows them locked: see [`GIVES`].
	 */
	gives: ([string, string[]])[],
};

export type SettingsFile = {
	file: string,
} & ({
	/**
	 *  `KEY=VALUE` lines. In a value `{romfs}` becomes the mod's romfs,
	 *  `{cheats}` its cheat folder and `{control}` the target's control
	 *  file.
	 */
	lines: string[],
	line?: never,
} | {
	/**
	 *  `KEY=VALUE` lines. In a value `{romfs}` becomes the mod's romfs,
	 *  `{cheats}` its cheat folder and `{control}` the target's control
	 *  file.
	 */
	line: string[],
	lines?: never,
});

/**  What a share code builds with, read without building it. */
export type SharedBuild = {
	settings: { [key in string]: Value },
	/**  How many checks its plando pins. */
	pins: number,
	test: TestSetup,
};

/**  Which side of the actor Link lands on, by its facing. */
export type Side = "front" | "back" | "left" | "right";

/**  One slot holding a save. */
export type SlotRow = {
	slot: number,
	/**  When the save was last written, in milliseconds. */
	stamp: number,
	/**  The slot Continue loads: the one written last. */
	continues: boolean,
	child: boolean | null,
	/**  The three stones and six medallions, each held or not. */
	stones: Cell[],
	medallions: Cell[],
	/**  Hearts, songs, Gold Skulltulas and rupees, each the save holds. */
	stats: Stat[],
	/**  Why the save couldn't be read, leaving the summary out. */
	error: string | null,
};

/**  Everything a page needs to pick up where the stream is. */
export type Snapshot = {
	status: LiveStatus,
	/**  The newest [`CAP`] events, across sessions. */
	events: Numbered[],
	/**  Events that fell off the top. */
	dropped: number,
	/**  The next event's number. */
	next: number,
};

export type Source = "Live" | "Saves";

/**  A seed's spots with their logic, and the checks logic can't show a way into. */
export type Spoiler = {
	spots: Spot[],
	events: RoundEvent[],
	unprovable: string[],
	start: Start,
	entrances: Door[],
};

/**  One chest in a seed. */
export type Spot = {
	hash: string,
	/**  The Banc folder the chest is placed in. */
	area: string,
	holder: string,
	vanilla: string,
	item: string,
	/**
	 *  Names from the game's text. Loading history fills in readable ids
	 *  for seeds from before they were kept.
	 */
	area_name?: string,
	/**  What it held in the vanilla game, plus "(big)" for a big chest. */
	chest_name?: string,
	item_name?: string,
	/**
	 *  Where it is, e.g. "Mido's House Back Left". Empty for gifts and for
	 *  seeds from before it was kept.
	 */
	place?: string,
	/**  Its name in the rule files, shown before `place` (`places::fill`). */
	custom?: string,
	/**
	 *  The playthrough round that collects it, from 1, for a check logic
	 *  placed whose item a rule names.
	 */
	round?: number | null,
	/**  On the Way of the Hero. */
	hero?: boolean,
	/**
	 *  The rule at its location, eras joined with "or". Empty where logic
	 *  has no location.
	 */
	need?: string,
	/**  The item ids that rule names. */
	need_items?: string[],
	/**
	 *  `Some(true)` when only a child can get it by logic, `Some(false)`
	 *  only an adult. `None` for both, or when logic can't tell.
	 */
	child?: boolean | null,
	/**
	 *  Given in the opening, as a setting keeps its scene from playing
	 *  (`gifts::pocket`).
	 */
	given?: boolean,
	/**
	 *  The Bools its stand-ins set once taken, which tick it without the
	 *  hook (`pickups::taken`).
	 */
	taken?: string[],
};

/**
 *  What's pending, cut to the edits that change the save, and how many
 *  things they change.
 */
export type Staged = {
	/**
	 *  `pending`'s edits that leave a value other than the presets do. A
	 *  cell clicked back to where it was drops out.
	 */
	edits: Edit[],
	/**
	 *  A grid cell counts once however many values its click wrote, and
	 *  any other value once.
	 */
	count: number,
};

/**  What logic counts Link as having before round 1. */
export type Start = {
	/**  Starting items and what presets hand over, by name. */
	items: Held[],
	/**  The settings logic's rules read that are on, by label. */
	settings: string[],
};

/**  What a new game starts holding, by word. */
export type StartInventory = { [key in string]: number };

/**  A number a row shows beside its icon. */
export type Stat = {
	label: string,
	icon: string,
	/**  What it draws with game art off. */
	glyph: Glyph,
	/**  In `per`ths of what the row shows, as a status field counts. */
	value: number,
	per: number,
};

export type Status = {
	/**  The game dump's path exists. Save already extracted it. */
	game: boolean,
	targets: TargetStatus[],
};

/**  One value a choice field can take, and what it reads as. */
export type StatusChoice = {
	value: string,
	label: string,
};

/**  One field of the panel. */
export type StatusField = {
	group: StatusGroup,
	label: string,
	hash: number,
	input: Input,
	/**  As the save holds it. */
	value: string,
	choices: StatusChoice[],
	/**
	 *  How many of the save's units make one shown: 4 for hearts, kept
	 *  in quarters.
	 */
	per: number,
	/**  The most it takes, in the save's units. */
	max: number | null,
	/**  Why the value looks wrong, without refusing it. */
	warn: string | null,
};

/**  Where a field sits in the panel. */
export type StatusGroup = "Meters" | "Gear" | "Age" | "Counters";

/**
 *  The steps of generating and installing a seed, in order, and the one
 *  of rebuilding a game.
 */
export type Step = "dump" | "checks" | "logic" | "placing" | "writing" | "spoiler" | "installing" | "rebuilding";

/**  What a run reports as it goes. */
export type StepEvent = { kind: "began"; step: Step } | 
/**  What the current step is doing now. */
{ kind: "detail"; text: string } | 
/**  A step ended, with its last detail. */
{ kind: "ended"; step: Step; detail: string; secs: number | null } | { kind: "end"; end: End; secs: number | null };

/**  An entry without its spots, for lists. */
export type Summary = {
	id: number,
	time: number,
	seed: string,
	/**  Stand-ins for the seed, settings and extras together. */
	icons: string[],
	/**  The seed, settings and extras as one line to share. */
	share: string,
	settings: { [key in string]: Value },
	label: Label,
	chests: number,
	changed: number,
	/**  Built with a test setup: a spawn, items, flags or quest steps. */
	test: boolean,
	/**  Built with a plando: items pinned to checks. */
	plando: boolean,
	/**  The slot, for a seed opened from an Archipelago `.apznx`. */
	ap_slot: string | null,
	/**  The slot plays DeathLink. */
	death_link: boolean,
};

/**  Where a seed installs and the game runs. Nothing here knows which one it is. */
export type Target = {
	name: string,
	/**  What Play opens, and whose process means the game is running. */
	app: string,
	/**  The mod folder: install writes `<mod_dir>/romfs`. */
	mod_dir: string,
	/**  The game's save folder, holding `slot_NN/`. */
	save_dir?: string | null,
	/**  Passed to `app` when Play starts it. `{game}` becomes the game dump. */
	args?: string[],
	/**
	 *  A file the game polls for input lines, for the play harness. A
	 *  settings line names it with `{control}`.
	 */
	control?: string | null,
	/**
	 *  The target's control socket. With it, live reads, dev tools
	 *  and the play harness go through the socket.
	 */
	bridge?: string | null,
	/**
	 *  `NAME=VALUE` lines set when Play starts `app`. `{bridge}` becomes
	 *  the socket.
	 */
	env?: string[],
	/**
	 *  `NAME=VALUE` lines the play harness adds to `env` when it starts
	 *  `app`, never the app's own Play: muted, slower, its own saves.
	 *  `{save}` becomes the run's save folder, and a line naming it is left
	 *  out when a start has none.
	 */
	harness_env?: string[],
	/**  How to rebuild a game that bakes exefs patches in at build time. */
	rebuild?: Rebuild | null,
	/**
	 *  The turn queue's game this target is part of: one of several slots
	 *  on a machine. None is this machine's game (`turn.here`).
	 */
	game?: string | null,
} & ({
	/**  Settings file lines written on install, e.g. `KEY={romfs}`. */
	settings_file?: SettingsFile | null,
} & {
	/**  Settings file lines written on install, e.g. `KEY={romfs}`. */
	settings_line?: SettingsFile | null,
});

export type TargetStatus = {
	name: string,
	app: boolean,
	mod_dir: boolean,
	running: boolean,
	/**
	 *  For a game that bakes the hook patch in at build time, whether its
	 *  build has the installed one.
	 */
	build?: Build | null,
};

/**
 *  Where a new game starts and what it holds, for a playtest: what the CLI's
 *  `--spawn`, `--give` and `--default` do.
 */
export type TestSetup = {
	/**  `MAP/SPOT`. */
	spawn?: string | null,
	/**  Pouch items by actor. */
	give?: string[],
	/**  `NAME=VALUE` new-game edits. */
	defaults?: string[],
	/**
	 *  `CHALLENGE=STEP` quest steps to move on, in order. A new game runs
	 *  them in its opening and Apply runs them live.
	 */
	progress?: string[],
	/**
	 *  A placed actor of the spawn's map to warp beside once there, when
	 *  applied live.
	 */
	near?: string | null,
	/**  Which side of `near` to land on. Front when unset. */
	side?: Side | null,
	/**  The hour to set before the teleport, when applied live. */
	hour?: number | null,
	/**  `NAME=VALUE` lines that hold once the test passes. Live only. */
	goals?: string[],
	/**  What a flag can't show, like the item a check should give. */
	expect?: string,
};

/**  How the grid looks, in the tab and the pop out. */
export type TrackerOptions = {
	size?: IconSize,
	/**  A CSS colour. */
	background?: string,
	/**  Every section once. The order within a column is the draw order. */
	sections?: Placement[],
};

/**  A window's part of `ui.json`, and the shared part. */
export type UiParts = {
	own: Value | null,
	shared: Value | null,
};

/**  The shared part changed, so the pop outs follow the main window. */
export type UiShared = Value;

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

export type View = {
	installed: Summary | null,
	/**  Newest first. */
	entries: Summary[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

